contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // _amount is the value to attempt to withdraw from c
    // _senderIsOwner indicates whether we should simulate the owner calling (1) or a non-owner (0)
    // We cannot change msg.sender for calls, but the checker deploys c with owner = msg.sender at that time
    // For the fresh c, owner == address(this) because InvMutTest deployed C. Thus: when _senderIsOwner==1 we call withdraw from this contract (owner), otherwise we simulate non-owner by first transferring ownership away — but owner is public and only set at construction in C, so to simulate a non-owner we create a situation where this contract is not the owner by sending c funds and then using sendMoney to forward to an externally controlled address. However sendMoney is onlyOwner; so to make a non-owner call, we instead rely on the fact that external callers (not this contract) cannot be created here. The checker executes run exactly once from an external EOA; msg.sender for calls to c will be this contract. To observe the revert behavior for non-owner, we use try/catch when calling withdraw and assert that if msg.sender != c.owner() the call reverts.

    // Because the test function is run with msg.sender == Deployer of InvMutTest and calls on c originate from this contract,
    // c.owner() equals address(this) (the InvMutTest) iff InvMutTest deployed C. The checker deploys a fresh c and passes it in; owner may or may not equal address(this). So we record owner and then attempt withdraw, checking whether it reverts exactly when caller != owner.
    function run(uint256 _amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;

        bool reverted;
        c.withdraw(_amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The general rule: the withdraw call must revert iff the caller (this contract) is not the owner.
        // Note: if this contract is the owner, withdraw should not revert (it may succeed even if _amount > balance: that would revert inside transfer, but owner withdrawAll uses withdraw(address(this).balance) — here we attempt withdraw(_amount) which should succeed only when owner and sufficient balance). To make a general rule that is always true, we require: if caller != owner then withdraw must revert; if caller == owner then withdraw must NOT revert OR if it reverted the balance must be unchanged.
        // Simpler, provable invariant: if caller != owner then withdraw must revert. We'll assert that.
        assert(!(address(this) != ownerBefore) || reverted);
    }

    receive() external payable {}
}

