// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.withdraw(_amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!(address(this) != ownerBefore) || reverted);
    }

    function testFuzz_run(uint256 _amount) public {
        _run(_amount);
    }

    receive() external payable {}
}
